(()=>{if(!navigator.clipboard?.writeText||!window.isSecureContext)return;document.querySelectorAll(".code-block-copy").forEach(e=>{e.hidden=!1,e.addEventListener("click",async t=>{t.preventDefault(),t.stopPropagation();const s=e.closest(".code-block")?.querySelector("code"),n=e.parentElement.querySelector(".code-block-status");if(!s||!n)return;try{await navigator.clipboard.writeText(s.textContent),n.textContent="Code copied."}catch{n.textContent="Copy unavailable. Select the code to copy it."}}),e.addEventListener("keydown",t=>{(t.key==="Enter"||t.key===" ")&&(t.preventDefault(),t.stopPropagation(),e.click())})})})()